#include <stdio.h>

void timesTen(int bowl[], int count) {
    int i;
    for (i = 0; i < count; i++) {
        bowl[i] = bowl[i] * 10;
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    int bowl[10];
    int i;
    for (i = 0; i < n; i++) {
        if (scanf("%d", &bowl[i]) != 1) {
            return 1;
        }
    }

    timesTen(bowl, n);

    for (i = 0; i < n; i++) {
        printf("%d\n", bowl[i]);
    }
    return 0;
}
